-- Development-only staged validation harness.
if type(isDebugEnabled)=="function" and isDebugEnabled()~=true then return {} end

local lightWorks=require "lightWorks/lightWorks_TestHarness"
local API=rawget(_G,"lightWorks")
local Harness={}
local FILE="theWorks Test Results - lightWorks.txt"
local KEY="lightWorks.StageTestSession.V1"
local TOKEN=tostring({})
local steps={
 {id="startup",feature="Canonical B47ANCED Spectrum/powerWorks load and result export",instruction="Run lightWorksTestAuto()."},
 {id="core",feature="Bulb, service, emission, UV, and power integration checks",instruction="Run lightWorksTestChecks()."},
 {id="visual_tour",feature="Guided portable-light visual tour",instruction="Run lightWorksTestTour() and enter PASS or the visible issue at each prompt."},
 {id="geometry",feature="Beam, halo, attachment, color, and weapon-light geometry",instruction="Compare the prompted devices and verify their visible footprints and orientations."},
 {id="patterns",feature="Light patterns and low-power flicker",instruction="Exercise the Light Pattern menu and drain a light below 10%; verify pattern, persistence, and flicker."},
 {id="world",feature="Dropped-light emission, controls, aim, drain, and cleanup",instruction="Drop active lights, use their controls, revisit the chunk, and confirm no stale or duplicate source."},
 {id="persistence",feature="Bulb, charge, pattern, and direction save persistence",instruction="Save/quit/reload a configured light, verify its state, then run lightWorksTestReload()."},
 {id="sandbox",feature="World-light sandbox control",instruction="Run lightWorksTestSandbox() and follow its safe setting-change instructions."},
 {id="multiplayer",feature="Hosted and dedicated authority",instruction="Verify one server-owned service/pattern/world state across clients; BLOCKED until available."},
}
local function safe(v)return tostring(v or""):gsub("[\r\n]+"," "):sub(1,500)end
local function now()local lib=rawget(_G,"os");if type(lib)=="table"and type(lib.date)=="function"then local ok,v=pcall(lib.date,"!%Y-%m-%dT%H:%M:%SZ");if ok and v then return tostring(v)end end;return"timestamp unavailable"end
local function player()local f=rawget(_G,"getSpecificPlayer");if type(f)=="function"then local ok,v=pcall(f,0);if ok and v then return v end end;f=rawget(_G,"getPlayer");if type(f)=="function"then local ok,v=pcall(f);if ok then return v end end end
local function data(v)if not v or type(v.getModData)~="function"then return nil end;local ok,d=pcall(v.getModData,v);return ok and type(d)=="table"and d or nil end
local function gameVersion()local f=rawget(_G,"getCore");if type(f)~="function"then return"unavailable"end;local ok,c=pcall(f);if ok and c then for _,n in ipairs({"getVersionNumber","getVersion"})do if type(c[n])=="function"then local read,v=pcall(c[n],c);if read and v~=nil then return tostring(v)end end end end;return"unavailable"end
local function session(create)local p=player();local d=data(p);if not d then return nil,nil,"local player ModData unavailable"end;if create and type(d[KEY])~="table"then d[KEY]={schemaVersion=1,sessionId="LIGHT-"..safe(now()),startedAt=now(),pzVersion=gameVersion(),modVersion=API.VERSION,runtimeToken=TOKEN,results={},commands={}}end;return d[KEY],p end
local function counts(s)local c={PASS=0,FAIL=0,BLOCKED=0,PENDING=0};for _,step in ipairs(steps)do local status=s.results[step.id]and s.results[step.id].status or"PENDING";c[status]=(c[status]or 0)+1 end;return c end
local function overall(s)local c=counts(s);if c.FAIL>0 then return"FAIL"elseif c.PENDING>0 then return"IN_PROGRESS"elseif c.BLOCKED>0 then return"BLOCKED"end;return"PASS"end
local function lines(s)local out={"theWorks in-game test results","Mod: B47ANCED Spectrum","Mod ID: lightWorks","Mod version: "..safe(s.modVersion),"Project Zomboid version: "..safe(s.pzVersion),"Session: "..safe(s.sessionId),"Started: "..safe(s.startedAt),"Generated: "..now(),"Dependencies enabled for this stage: powerWorks","Overall session status: "..overall(s),"","FEATURE RESULTS"};for i,step in ipairs(steps)do local r=s.results[step.id]or{status="PENDING",note=""};out[#out+1]=string.format("%02d. [%s] %s | %s | %s",i,r.status,step.id,step.feature,safe(r.note))end;out[#out+1]="";out[#out+1]="COMMAND LOG";for i,e in ipairs(s.commands)do out[#out+1]=string.format("%03d. %s | %s | %s | %s | %s",i,safe(e.at),safe(e.command),safe(e.feature),safe(e.outcome),safe(e.detail))end;return out end
local function writeReport(s)local f=rawget(_G,"getFileWriter");if type(f)~="function"then return false,"getFileWriter unavailable"end;local ok,err=pcall(function()local w=f(FILE,true,false);if not w then error("writer unavailable")end;for _,line in ipairs(lines(s))do if type(w.writeln)=="function"then w:writeln(line)else w:write(line.."\n")end end;if type(w.close)=="function"then w:close()end end);return ok,ok and nil or safe(err)end
local function say(v)print("[lightWorks][StageTest] "..v)end
local function record(s,id,status,note)s.results[id]={status=status,note=safe(note),recordedAt=now()}end
local function finish(s,command,feature,status,detail)s.commands[#s.commands+1]={at=now(),command=command,feature=feature,outcome=status,detail=safe(detail)};while #s.commands>128 do table.remove(s.commands,1)end;local saved,err=writeReport(s);say(command..": "..status.." "..safe(detail));say(saved and("Results saved to Zomboid/Lua/"..FILE)or("Result export failed: "..safe(err)));return status=="PASS",detail end
local function pending(s)for _,step in ipairs(steps)do if not s.results[step.id]then return step end end end
function Harness.auto()local s,_,err=session(true);if not s then say(err);return false,err end;local power=(rawget(_G,"B47ANCEDPower")or rawget(_G,"powerWorks")or lightWorks.powerWorks);local canonical=API==rawget(_G,"lightWorks")and API.VERSION==s.modVersion;local dependency=type(power)=="table"and type(power.getConsumerPowerState)=="function";local definitions=API.isRegisteredLight("Base.HandTorch")and API.isRegisteredBulb("Base.LightBulbRed");local surfaces=type(API.getEmission)=="function"and type(API.installBulb)=="function"and type(API.supportsWorldEmission)=="function";local writer=writeReport(s);local pass=canonical and dependency and definitions and surfaces and writer;local detail=string.format("canonical=%s dependency=%s definitions=%s surfaces=%s writer=%s",tostring(canonical),tostring(dependency),tostring(definitions),tostring(surfaces),tostring(writer));record(s,"startup",pass and"PASS"or"FAIL",detail);return finish(s,"lightWorksTestAuto()","startup",pass and"PASS"or"FAIL",detail)end
function Harness.start(reset)local s,p,err=session(true);if not s then say(err);return false,err end;if reset==true then data(p)[KEY]=nil;s=session(true)end;Harness.auto();local step=pending(s);say("Session started. Enable powerWorks and B47ANCED Spectrum only.");if step then say("NEXT ["..step.id.."] "..step.instruction)end;return true,s.sessionId end
function Harness.checks()local s=session(false);if not s then say("No session; run lightWorksTestStart(true)");return false end;local ok,result=lightWorks.runChecks();local pass=ok==true and type(result)=="table"and tonumber(result.failed)==0;local detail=string.format("passed=%s failed=%s",safe(result and result.passed),safe(result and result.failed));record(s,"core",pass and"PASS"or"FAIL",detail);return finish(s,"lightWorksTestChecks()","core",pass and"PASS"or"FAIL",detail)end
function Harness.tour()local s=session(false);if not s then say("No session");return false end;lightWorks.whenTourCompletes(function(results)local issues=0;for _,r in ipairs(results or{})do if string.upper(tostring(r.report or""))~="PASS"then issues=issues+1 end end;record(s,"visual_tour",issues==0 and"PASS"or"FAIL","lights="..tostring(#(results or{})).." issues="..tostring(issues));finish(s,"LW guided tour completion","visual_tour",issues==0 and"PASS"or"FAIL","issues="..tostring(issues))end);local started,reason=lightWorks.startTour();return finish(s,"lightWorksTestTour()","visual_tour",started and"BLOCKED"or"FAIL",started and"guided prompts started; result records when tour completes"or reason)end
function Harness.reloadStatus()local s=session(false);if not s then say("No session");return false end;local changed=s.runtimeToken~=TOKEN;if changed then record(s,"persistence","PASS","new Lua runtime observed; tester confirmed configured light state")end;return finish(s,"lightWorksTestReload()","persistence",changed and"PASS"or"BLOCKED",changed and"runtime reload observed"or"save/quit/reload still required")end
function Harness.sandbox()local s=session(false);if not s then say("No session");return false end;local root=rawget(_G,"SandboxVars");local values=root and root.lightWorks;local value=values and values.EnableWorldEmitters;if type(value)~="boolean"then return finish(s,"lightWorksTestSandbox()","sandbox","FAIL","lightWorks world-light setting unavailable")end;if s.sandboxOriginal==nil then s.sandboxOriginal=value;s.sandboxRequested=not value;say("B47ANCED SPECTRUM TEST — Settings");say("Open Sandbox Options > B47ANCED Spectrum and set Enable dropped and placed world lights to "..(s.sandboxRequested and"ON"or"OFF")..". Apply it, return, and run lightWorksTestSandbox() again.");return finish(s,"lightWorksTestSandbox()","sandbox","BLOCKED","waiting for requested setting change")end;if value~=s.sandboxRequested then return finish(s,"lightWorksTestSandbox()","sandbox","BLOCKED","setting has not changed yet")end;record(s,"sandbox","PASS","runtime observed the requested world-light setting change");say("Verified. Restore the setting to "..(s.sandboxOriginal and"ON"or"OFF").." after testing.");return finish(s,"lightWorksTestSandbox()","sandbox","PASS","original="..tostring(s.sandboxOriginal).." changed="..tostring(value))end
function Harness.recordCurrent(status,note)local s=session(false);if not s then say("No session");return false end;local step=pending(s);if not step then say("All steps recorded");return false end;record(s,step.id,status,note);finish(s,"lightWorksTest"..status:sub(1,1)..status:sub(2):lower().."()",step.id,status,note);return true end
function Harness.report()local s=session(false);if not s then say("No session");return false end;for _,line in ipairs(lines(s))do say(line)end;return writeReport(s)end
function Harness.where()say("Windows result file: %USERPROFILE%\\Zomboid\\Lua\\"..FILE);return FILE end
lightWorksTestStart=function(reset)return Harness.start(reset)end;lightWorksTestAuto=function()return Harness.auto()end;lightWorksTestChecks=function()return Harness.checks()end;lightWorksTestTour=function()return Harness.tour()end;lightWorksTestReload=function()return Harness.reloadStatus()end;lightWorksTestSandbox=function()return Harness.sandbox()end;lightWorksTestPass=function(note)return Harness.recordCurrent("PASS",note)end;lightWorksTestFail=function(note)return Harness.recordCurrent("FAIL",note)end;lightWorksTestBlocked=function(note)return Harness.recordCurrent("BLOCKED",note)end;lightWorksTestReport=function()return Harness.report()end;lightWorksTestWhere=function()return Harness.where()end
API.StageTestHarness=Harness;say("Ready: lightWorksTestStart(true); results export to Zomboid/Lua/"..FILE);return Harness
